<template>
  <div class="page-heading"><div><h1 class="page-title">推广数据</h1><p>录入和查看推广账户每日运营数据；归档后的数据不会再被自动同步覆盖。</p></div><div><el-button @click="syncVisible = true">手动同步</el-button><el-button type="primary" @click="openMetric()">录入日数据</el-button></div></div>
  <div class="content-panel"><div class="toolbar"><el-select v-model="query.accountId" clearable placeholder="全部推广账户" style="width:220px"><el-option v-for="a in accounts" :key="a.id" :label="`${a.project} · ${a.platform} · ${a.name}`" :value="a.id" /></el-select><el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" /><el-button type="primary" :loading="loading" @click="load">查询</el-button></div>
    <el-table :data="rows" v-loading="loading" border show-summary :summary-method="summary" class="metric-table" :default-sort="{ prop: 'statDate', order: 'descending' }"><el-table-column prop="statDate" label="日期" width="96" fixed /><el-table-column label="账户" width="168" show-overflow-tooltip><template #default="{ row }">{{ row.account.project }} · {{ row.account.platform }} · {{ row.account.name }}</template></el-table-column><el-table-column v-if="isVisible('spend')" prop="spend" :label="fieldLabel('spend', '消费')" width="100" /><el-table-column v-if="isVisible('impressions')" prop="impressions" :label="fieldLabel('impressions', '展现')" width="100" /><el-table-column v-if="isVisible('clicks')" prop="clicks" :label="fieldLabel('clicks', '点击')" width="85" /><el-table-column v-if="isVisible('clickRate')" :label="fieldLabel('clickRate', '点击率')" width="90"><template #default="{ row }">{{ rate(row.calculated.clickRate) }}</template></el-table-column><el-table-column v-if="isVisible('leads')" prop="leads" :label="fieldLabel('leads', '总表单')" width="90" /><el-table-column v-if="isVisible('validLeads')" prop="validLeads" :label="fieldLabel('validLeads', '有效表单')" width="100" /><el-table-column v-if="isVisible('validRate')" :label="fieldLabel('validRate', '有效率')" width="90"><template #default="{ row }">{{ rate(row.calculated.validRate) }}</template></el-table-column><el-table-column v-if="isVisible('averageCost')" :label="fieldLabel('averageCost', '平均成本')" width="100"><template #default="{ row }">{{ number(row.calculated.averageCost) }}</template></el-table-column><el-table-column v-if="isVisible('validCost')" :label="fieldLabel('validCost', '有效成本')" width="100"><template #default="{ row }">{{ number(row.calculated.validCost) }}</template></el-table-column><el-table-column v-if="isVisible('appointments')" prop="appointments" :label="fieldLabel('appointments', '到院')" width="75" /><el-table-column v-if="isVisible('transactions')" prop="transactions" :label="fieldLabel('transactions', '成交')" width="75" /><el-table-column v-if="isVisible('conversionRate')" :label="fieldLabel('conversionRate', '成交率')" width="90"><template #default="{ row }">{{ rate(row.calculated.conversionRate) }}</template></el-table-column><el-table-column v-if="isVisible('arrivalRate')" :label="fieldLabel('arrivalRate', '到诊率')" width="90"><template #default="{ row }">{{ rate(row.calculated.arrivalRate) }}</template></el-table-column><el-table-column v-if="isVisible('validArrivalRate')" :label="fieldLabel('validArrivalRate', '有效到诊率')" width="110"><template #default="{ row }">{{ rate(row.calculated.validArrivalRate) }}</template></el-table-column><el-table-column v-if="isVisible('arrivalCost')" :label="fieldLabel('arrivalCost', '到院成本')" width="100"><template #default="{ row }">{{ number(row.calculated.arrivalCost) }}</template></el-table-column><el-table-column v-if="isVisible('revenue')" prop="revenue" :label="fieldLabel('revenue', '实收')" width="100" /><el-table-column v-if="isVisible('roi')" :label="fieldLabel('roi', '投产比')" width="90"><template #default="{ row }">{{ number(row.calculated.roi) }}</template></el-table-column><el-table-column v-for="field in customVisibleFields" :key="field.id" :label="field.label" min-width="100"><template #default="{ row }">{{ row.customMetrics?.[field.key] ?? '-' }}</template></el-table-column><el-table-column label="操作" width="130" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openMetric(row)">编辑</el-button><el-button link type="danger" @click="removeMetric(row)">删除</el-button></template></el-table-column></el-table>
  </div>
  <el-dialog v-model="metricVisible" :title="metricForm.id ? '编辑日数据' : '录入日数据'" width="760px"><el-form :model="metricForm" label-width="90px" class="metric-form"><el-form-item label="推广账户" required><el-select v-model="metricForm.accountId" filterable style="width:100%"><el-option v-for="a in activeAccounts" :key="a.id" :label="`${a.project} · ${a.platform} · ${a.name}`" :value="a.id" /></el-select></el-form-item><el-form-item label="日期" required><el-date-picker v-model="metricForm.statDate" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-row :gutter="16"><el-col v-for="field in inputFields" v-show="isVisible(field.key)" :key="field.key" :span="8"><el-form-item :label="fieldLabel(field.key, field.label)"><el-input-number v-model="metricForm[field.key]" :min="0" :precision="field.money ? 2 : 0" controls-position="right" style="width:100%" /></el-form-item></el-col><el-col v-for="field in customVisibleFields" :key="field.id" :span="8"><el-form-item :label="field.label"><el-input-number v-if="field.dataType === 'NUMBER'" v-model="customValues[field.key]" :min="0" controls-position="right" style="width:100%" /><el-input v-else v-model="customValues[field.key]" /></el-form-item></el-col></el-row><el-form-item label="备注"><el-input v-model="metricForm.remark" type="textarea" :rows="2" /></el-form-item><el-form-item v-if="metricForm.id" label="归档保护"><el-switch v-model="metricArchived" active-text="归档后不自动同步" /></el-form-item></el-form><template #footer><el-button @click="metricVisible = false">取消</el-button><el-button type="primary" :loading="saving" @click="saveMetric">保存</el-button></template></el-dialog>
  <el-dialog v-model="accountsVisible" title="推广账户" width="820px"><div class="account-actions"><el-button type="primary" @click="openAccount()">添加账户</el-button></div><el-table :data="accounts" border><el-table-column prop="project" label="项目" width="90" /><el-table-column prop="platform" label="渠道" width="120" /><el-table-column prop="name" label="账户名称" /><el-table-column prop="accountNo" label="账号 ID" /><el-table-column label="状态" width="90"><template #default="{ row }"><el-tag :type="row.status === 'ACTIVE' ? 'success' : 'info'">{{ row.status === 'ACTIVE' ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="130"><template #default="{ row }"><el-button link type="primary" @click="openAccount(row)">编辑</el-button><el-button link type="danger" @click="removeAccount(row)">删除</el-button></template></el-table-column></el-table></el-dialog>
  <el-dialog v-model="accountVisible" :title="accountForm.id ? '编辑推广账户' : '添加推广账户'" width="520px"><el-form :model="accountForm" label-width="90px"><el-form-item label="项目" required><el-radio-group v-model="accountForm.project"><el-radio value="重庆">重庆</el-radio><el-radio value="绵阳">绵阳</el-radio></el-radio-group></el-form-item><el-form-item label="渠道" required><el-input v-model="accountForm.platform" placeholder="如：腾讯广告、巨量引擎、本地推" /></el-form-item><el-form-item label="账户名称" required><el-input v-model="accountForm.name" /></el-form-item><el-form-item label="账号 ID"><el-input v-model="accountForm.accountNo" /></el-form-item><el-form-item label="状态"><el-radio-group v-model="accountForm.status"><el-radio value="ACTIVE">启用</el-radio><el-radio value="DISABLED">停用</el-radio></el-radio-group></el-form-item><el-form-item label="备注"><el-input v-model="accountForm.remark" type="textarea" /></el-form-item></el-form><template #footer><el-button @click="accountVisible = false">取消</el-button><el-button type="primary" @click="saveAccount">保存</el-button></template></el-dialog>
  <el-dialog v-model="syncVisible" title="手动同步平台日数据" width="520px"><el-form :model="syncForm" label-width="90px"><el-form-item label="同步日期" required><el-date-picker v-model="syncForm.statDate" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="平台"><el-radio-group v-model="syncForm.provider"><el-radio value="">全部已启用平台</el-radio><el-radio value="TENCENT_ADS">腾讯营销</el-radio><el-radio value="OCEANENGINE">巨量引擎</el-radio></el-radio-group></el-form-item><el-form-item label="推广账户"><el-select v-model="syncForm.accountIds" multiple collapse-tags clearable placeholder="不选则同步该平台全部启用账户" style="width:100%"><el-option v-for="item in accounts" :key="item.id" :label="`${item.project} · ${item.platform} · ${item.name}`" :value="item.id" /></el-select></el-form-item></el-form><template #footer><el-button @click="syncVisible=false">取消</el-button><el-button type="primary" :loading="syncing" @click="syncData">开始同步</el-button></template></el-dialog>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { archivePromotionDailyMetric, createPromotionAccount, createPromotionDailyMetric, deletePromotionAccount, deletePromotionDailyMetric, getPromotionAccounts, getPromotionDailyMetrics, getPromotionMetricFields, syncPromotionDailyMetrics, type PromotionAccountItem, type PromotionDailyMetricItem, type PromotionMetricFieldItem, updatePromotionAccount, updatePromotionDailyMetric } from '../api/admin';
const localDate = (offsetDays = 0) => { const date = new Date(); date.setDate(date.getDate() + offsetDays); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; };
const accounts = ref<PromotionAccountItem[]>([]); const fields = ref<PromotionMetricFieldItem[]>([]); const rows = ref<PromotionDailyMetricItem[]>([]); const loading = ref(false); const saving = ref(false); const yesterday = localDate(-1); const dateRange = ref<string[]>([yesterday, yesterday]); const query = reactive({ accountId: '' }); const metricVisible = ref(false); const accountsVisible = ref(false); const accountVisible = ref(false);
const syncVisible = ref(false); const syncing = ref(false); const syncForm = reactive({ statDate: yesterday, provider: '' as '' | 'TENCENT_ADS' | 'OCEANENGINE', accountIds: [] as string[] });
const metricArchived = ref(false);
const inputFields = [{ key: 'spend', label: '消费', money: true }, { key: 'impressions', label: '展现', money: false }, { key: 'clicks', label: '点击', money: false }, { key: 'leads', label: '总表单', money: false }, { key: 'validLeads', label: '有效表单', money: false }, { key: 'appointments', label: '到院', money: false }, { key: 'transactions', label: '成交', money: false }, { key: 'revenue', label: '实收', money: true }] as const;
const blankMetric = () => ({ id: '', accountId: '', statDate: yesterday, spend: 0, impressions: 0, clicks: 0, leads: 0, validLeads: 0, appointments: 0, transactions: 0, revenue: 0, remark: '' }); const metricForm = reactive(blankMetric()); const customValues = reactive<Record<string, string | number>>({}); const accountForm = reactive({ id: '', project: '重庆' as '重庆' | '绵阳', platform: '', name: '', accountNo: '', status: 'ACTIVE' as 'ACTIVE' | 'DISABLED', remark: '' });
const activeAccounts = computed(() => accounts.value.filter((item) => item.status === 'ACTIVE' || item.id === metricForm.accountId)); const customVisibleFields = computed(() => fields.value.filter((field) => field.source === 'CUSTOM' && field.isVisible)); const rate = (value: number | null) => value === null || !Number.isFinite(value) ? '—' : `${(value * 100).toFixed(2)}%`; const number = (value: number | null) => value === null || !Number.isFinite(value) ? '—' : value.toFixed(2); const isVisible = (key: string) => fields.value.find((field) => field.key === key)?.isVisible !== false; const fieldLabel = (key: string, fallback: string) => fields.value.find((field) => field.key === key)?.label || fallback;
async function loadAccounts() { accounts.value = await getPromotionAccounts(); } async function loadFields() { fields.value = await getPromotionMetricFields(); }
function summary({ columns }: { columns: Array<{ label: string; property: string }> }) { const total = rows.value.reduce((result, row) => ({ spend: result.spend + row.spend, impressions: result.impressions + row.impressions, clicks: result.clicks + row.clicks, leads: result.leads + row.leads, validLeads: result.validLeads + row.validLeads, appointments: result.appointments + row.appointments, transactions: result.transactions + row.transactions, revenue: result.revenue + row.revenue }), { spend: 0, impressions: 0, clicks: 0, leads: 0, validLeads: 0, appointments: 0, transactions: 0, revenue: 0 }); const calc = { clickRate: total.impressions ? total.clicks / total.impressions : null, validRate: total.leads ? total.validLeads / total.leads : null, averageCost: total.leads ? total.spend / total.leads : null, validCost: total.validLeads ? total.spend / total.validLeads : null, conversionRate: total.appointments ? total.transactions / total.appointments : null, arrivalRate: total.leads ? total.appointments / total.leads : null, validArrivalRate: total.validLeads ? total.appointments / total.validLeads : null, arrivalCost: total.appointments ? total.spend / total.appointments : null, roi: total.spend ? total.revenue / total.spend : null }; const labels: Record<string, string> = {}; fields.value.forEach((field) => { labels[field.label] = field.key; }); return columns.map((column, index) => index === 0 ? '合计' : index === 1 ? '' : column.property && column.property in total ? String(total[column.property as keyof typeof total]) : labels[column.label] ? (labels[column.label].includes('Rate') ? rate(calc[labels[column.label] as keyof typeof calc] as number | null) : number(calc[labels[column.label] as keyof typeof calc] as number | null)) : ''); }
async function load() { loading.value = true; try { rows.value = await getPromotionDailyMetrics({ accountId: query.accountId, dateFrom: dateRange.value?.[0] || '', dateTo: dateRange.value?.[1] || '' }); } finally { loading.value = false; } }
function openMetric(row?: PromotionDailyMetricItem) { Object.assign(metricForm, blankMetric(), row ? { ...row, remark: row.remark || '' } : {}); metricArchived.value = Boolean(row?.isArchived); Object.keys(customValues).forEach((key) => delete customValues[key]); fields.value.filter((field) => field.source === 'CUSTOM').forEach((field) => { customValues[field.key] = row?.customMetrics?.[field.key] ?? (field.dataType === 'NUMBER' ? 0 : ''); }); metricVisible.value = true; }
async function saveMetric() { if (!metricForm.accountId) return ElMessage.warning('请选择推广账户'); saving.value = true; try { const { id: _id, ...data } = { ...metricForm, customMetrics: { ...customValues } }; if (metricForm.id) { await updatePromotionDailyMetric(metricForm.id, data); await archivePromotionDailyMetric(metricForm.id, metricArchived.value); } else await createPromotionDailyMetric(data); ElMessage.success('已保存'); metricVisible.value = false; await load(); } finally { saving.value = false; } }
async function syncData() { syncing.value = true; try { const result = await syncPromotionDailyMetrics({ statDate: syncForm.statDate, ...(syncForm.provider ? { provider: syncForm.provider } : {}), ...(syncForm.accountIds.length ? { accountIds: syncForm.accountIds } : {}) }); const success = result.reduce((sum, item) => sum + item.synced, 0); const errors = result.flatMap((item) => item.errors); ElMessage[errors.length ? 'warning' : 'success'](`同步完成：成功 ${success} 条${errors.length ? `；${errors.join('；')}` : ''}`); syncVisible.value = false; await load(); } finally { syncing.value = false; } }
function openAccount(row?: PromotionAccountItem) { Object.assign(accountForm, { id: '', project: '重庆', platform: '', name: '', accountNo: '', status: 'ACTIVE', remark: '' }, row || {}); accountVisible.value = true; }
async function saveAccount() { if (!accountForm.platform.trim() || !accountForm.name.trim()) return ElMessage.warning('请填写渠道和账户名称'); const { id: _id, ...data } = accountForm; if (accountForm.id) await updatePromotionAccount(accountForm.id, data); else await createPromotionAccount(data); ElMessage.success('账户已保存'); accountVisible.value = false; await loadAccounts(); }
async function removeMetric(row: PromotionDailyMetricItem) { await ElMessageBox.confirm(`确认删除 ${row.statDate} 的日数据吗？`, '删除确认', { type: 'warning' }); await deletePromotionDailyMetric(row.id); ElMessage.success('已删除'); await load(); } async function removeAccount(row: PromotionAccountItem) { await ElMessageBox.confirm(`删除账户“${row.name}”会同时删除其全部日数据，确认继续吗？`, '删除确认', { type: 'warning' }); await deletePromotionAccount(row.id); ElMessage.success('已删除'); await loadAccounts(); await load(); }
onMounted(async () => { await Promise.all([loadAccounts(), loadFields()]); await load(); });
</script>
<style scoped>.toolbar,.account-actions { display:flex; gap:12px; flex-wrap:wrap; margin-bottom:18px; }.page-heading { display:flex; justify-content:space-between; align-items:flex-start; gap:16px; margin-bottom:20px; }.page-title { margin:0 0 6px; }.page-heading p { margin:0; color:var(--admin-text-muted); }.metric-table { width:100%; }.metric-table :deep(.el-table__cell),.metric-table :deep(.cell) { white-space:nowrap; }.metric-form :deep(.el-form-item) { margin-bottom:16px; }</style>
